B.a3T=new A.ci("Tandem Button","\u0632\u0631 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642")
B.a3V=new A.ci("A confirmation bar with one clear next step. Dark on paper, cream in the dark, and never wider than it needs to be.","\u0634\u0631\u064a\u0637 \u062a\u0623\u0643\u064a\u062f \u0628\u062e\u0637\u0648\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0627\u0636\u062d\u0629. \u062f\u0627\u0643\u0646 \u0639\u0644\u0649 \u0627\u0644\u0648\u0631\u0642\u060c \u0641\u0627\u062a\u062d \u0641\u064a \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u062f\u0627\u0643\u0646\u060c \u0648\u0644\u0627 \u064a\u062a\u0651\u0633\u0639 \u0623\u0643\u062b\u0631 \u0645\u0646 \u062d\u0627\u062c\u062a\u0647.")
B.a3W=new A.ci("A tactile key with smoothed corners and a visible 4px press. The color comes from the theme, so it follows the palette.","\u0632\u0631 \u0645\u0644\u0645\u0648\u0633 \u0628\u0632\u0648\u0627\u064a\u0627 \u0646\u0627\u0639\u0645\u0629 \u0648\u0636\u063a\u0637\u0629 \u0645\u0631\u0626\u064a\u0629 \u0628\u0645\u0642\u062f\u0627\u0631 4 \u0628\u0643\u0633\u0644. \u0644\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u062b\u064a\u0645 \u0641\u064a\u062a\u0628\u0639 \u0644\u0648\u062d\u0629 \u0627\u0644\u0623\u0644\u0648\u0627\u0646.")
B.a3Y=new A.ci("A solid pill with a bright companion coin. The coin nudges forward on hover, so the label and icon move as one pair.","\u0632\u0631 \u0645\u0645\u062a\u0644\u0626 \u0628\u0642\u0631\u0635 \u0645\u0644\u0648\u0651\u0646 \u064a\u0631\u0627\u0641\u0642\u0647. \u064a\u062a\u0642\u062f\u0651\u0645 \u0627\u0644\u0642\u0631\u0635 \u0642\u0644\u064a\u0644\u064b\u0627 \u0639\u0646\u062f \u0627\u0644\u0645\u0631\u0648\u0631\u060c \u0641\u064a\u062a\u062d\u0631\u0651\u0643 \u0627\u0644\u0646\u0635 \u0648\u0627\u0644\u0623\u064a\u0642\u0648\u0646\u0629 \u0643\u0648\u062d\u062f\u0629 \u0648\u0627\u062d\u062f\u0629.")
B.a3Z=new A.ci("Filter Pill","\u0632\u0631 \u0627\u0644\u062a\u0635\u0641\u064a\u0629")
B.a4_=new A.ci("A friendly lock for subscriber-only content, with one clear way in.","\u0642\u0641\u0644 \u0648\u062f\u0648\u062f \u0644\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u062e\u0635\u0635 \u0644\u0644\u0623\u0639\u0636\u0627\u0621\u060c \u0645\u0639 \u0637\u0631\u064a\u0642 \u0648\u0627\u062d\u062f \u0648\u0627\u0636\u062d \u0644\u0644\u062f\u062e\u0648\u0644.")
B.a40=new A.ci("A round icon action with a satellite dot. On hover, the dot completes one quiet orbit around the button.","\u0632\u0631 \u0623\u064a\u0642\u0648\u0646\u0629 \u062f\u0627\u0626\u0631\u064a \u0628\u0646\u0642\u0637\u0629 \u062a\u062f\u0648\u0631 \u062d\u0648\u0644\u0647. \u0639\u0646\u062f \u0627\u0644\u0645\u0631\u0648\u0631\u060c \u062a\u0643\u0645\u0644 \u0627\u0644\u0646\u0642\u0637\u0629 \u0645\u062f\u0627\u0631\u064b\u0627 \u0647\u0627\u062f\u0626\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u062d\u0648\u0644 \u0627\u0644\u0632\u0631.")
B.a41=new A.ci("Squircle Button","\u0632\u0631 \u0633\u0643\u0648\u064a\u0631\u0643\u0644")
B.a42=new A.ci("A small room with two doors. The accent thumb glides to the chosen side, and the direction reverses correctly in Arabic.","\u063a\u0631\u0641\u0629 \u0635\u063a\u064a\u0631\u0629 \u0628\u0628\u0627\u0628\u064a\u0646. \u064a\u0646\u0632\u0644\u0642 \u0627\u0644\u0645\u0642\u0628\u0636 \u0627\u0644\u0645\u0644\u0648\u0651\u0646 \u0625\u0644\u0649 \u0627\u0644\u062c\u0647\u0629 \u0627\u0644\u0645\u062e\u062a\u0627\u0631\u0629\u060c \u0648\u064a\u0646\u0639\u0643\u0633 \u0627\u062a\u062c\u0627\u0647\u0647 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0641\u064a \u0627\u0644\u0639\u0631\u0628\u064a\u0629.")
B.a43=new A.ci("Date Strip","\u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0648\u0627\u0631\u064a\u062e")
B.a46=new A.ci("A calm progress rail with a marker at the leading edge. The fill eases forward; the number stays still and legible.","\u0645\u0633\u0627\u0631 \u062a\u0642\u062f\u0645 \u0647\u0627\u062f\u0626 \u0628\u0645\u0624\u0634\u0631 \u0639\u0646\u062f \u062d\u0627\u0641\u0629 \u0627\u0644\u0627\u0645\u062a\u0644\u0627\u0621. \u064a\u062a\u0642\u062f\u0651\u0645 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0646\u0639\u0648\u0645\u0629\u060c \u0648\u064a\u0628\u0642\u0649 \u0627\u0644\u0631\u0642\u0645 \u062b\u0627\u0628\u062a\u064b\u0627 \u0648\u0648\u0627\u0636\u062d\u064b\u0627.")
B.a47=new A.ci("A title, a short body, and room for an action. The line height changes for Arabic so the block keeps the same calm rhythm.","\u0639\u0646\u0648\u0627\u0646 \u0648\u0646\u0635 \u0642\u0635\u064a\u0631 \u0648\u0645\u0633\u0627\u062d\u0629 \u0644\u0625\u062c\u0631\u0627\u0621. \u064a\u062a\u063a\u064a\u0651\u0631 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0633\u0637\u0631 \u0641\u064a \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0644\u062a\u062d\u0627\u0641\u0638 \u0627\u0644\u0643\u062a\u0644\u0629 \u0639\u0644\u0649 \u0625\u064a\u0642\u0627\u0639\u0647\u0627 \u0627\u0644\u0647\u0627\u062f\u0626.")
B.a48=new A.ci("Access Gate","\u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u0639\u0636\u0648\u064a\u0629")
B.a49=new A.ci("Progress Rail","\u062d\u0627\u0644\u0629 \u0627\u0644\u062a\u0642\u062f\u0645")
B.a4a=new A.ci("Orbit Button","\u0632\u0631 \u0627\u0644\u0645\u062f\u0627\u0631")
B.a4b=new A.ci("Point Badge","\u0634\u0627\u0631\u0629 \u0627\u0644\u0646\u0642\u0627\u0637")
B.a4c=new A.ci("Crew Row","\u0635\u0641 \u0627\u0644\u0641\u0631\u064a\u0642")
B.a4d=new A.ci("Tally Stepper","\u0639\u062f\u0651\u0627\u062f \u0627\u0644\u0643\u0645\u064a\u0629")
B.a4e=new A.ci("A labelled field with its helper kept close. Focus wraps the whole note in a solid accent ring instead of a glow.","\u062d\u0642\u0644 \u0628\u0639\u0646\u0648\u0627\u0646 \u0648\u0645\u0644\u0627\u062d\u0638\u0629 \u0642\u0631\u064a\u0628\u0629 \u0645\u0646\u0647. \u064a\u062d\u064a\u0637 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0628\u0627\u0644\u062d\u0642\u0644 \u0628\u062d\u0644\u0642\u0629 \u0648\u0627\u0636\u062d\u0629 \u0628\u0644\u0648\u0646 \u0627\u0644\u062a\u0645\u064a\u064a\u0632 \u0628\u062f\u0644\u064b\u0627 \u0645\u0646 \u062a\u0648\u0647\u0651\u062c.")
B.a4f=new A.ci("A bounded number control. The count rolls when it changes, and the two round keys politely disable themselves at the ends.","\u0623\u062f\u0627\u0629 \u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0639\u062f\u062f \u0645\u062d\u062f\u0648\u062f. \u064a\u062a\u062f\u062d\u0631\u062c \u0627\u0644\u0631\u0642\u0645 \u0639\u0646\u062f \u062a\u063a\u064a\u064a\u0631\u0647\u060c \u0648\u064a\u062a\u0639\u0637\u0651\u0644 \u0627\u0644\u0645\u0641\u062a\u0627\u062d\u0627\u0646 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0639\u0646\u062f \u0628\u0644\u0648\u063a \u0627\u0644\u062d\u062f\u064a\u0646.")
B.a4g=new A.ci("Soft Toast","\u062a\u0646\u0628\u064a\u0647 \u0646\u0627\u0639\u0645")
B.a4h=new A.ci("A quiet page-ending with a dashed frame and a stack of blank tiles. There is one way forward, and it is obvious.","\u0646\u0647\u0627\u064a\u0629 \u0647\u0627\u062f\u0626\u0629 \u0644\u0644\u0635\u0641\u062d\u0629 \u0628\u0625\u0637\u0627\u0631 \u0645\u062a\u0642\u0637\u0651\u0639 \u0648\u0631\u0632\u0645\u0629 \u0628\u0637\u0627\u0642\u0627\u062a \u0641\u0627\u0631\u063a\u0629. \u0647\u0646\u0627\u0643 \u0637\u0631\u064a\u0642 \u0648\u0627\u062d\u062f \u0644\u0644\u0645\u062a\u0627\u0628\u0639\u0629\u060c \u0648\u0647\u0648 \u0648\u0627\u0636\u062d.")
B.a4i=new A.ci("Field Note","\u062d\u0642\u0644 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629")
B.a4j=new A.ci("Title Stack","\u0643\u062a\u0644\u0629 \u0627\u0644\u0639\u0646\u0648\u0627\u0646")
B.a4k=new A.ci("Empty Nest","\u062d\u0627\u0644\u0629 \u0641\u0631\u0627\u063a")
B.a4n=new A.ci("A selectable pill with a fixed dot slot. The dot wakes up when selected, and the row never shifts as the choice moves.","\u0632\u0631 \u0627\u062e\u062a\u064a\u0627\u0631 \u0628\u0646\u0642\u0637\u0629 \u062b\u0627\u0628\u062a\u0629 \u0627\u0644\u0645\u0648\u0636\u0639. \u062a\u0633\u062a\u064a\u0642\u0638 \u0627\u0644\u0646\u0642\u0637\u0629 \u0639\u0646\u062f \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u060c \u0648\u0644\u0627 \u064a\u062a\u062d\u0631\u0651\u0643 \u0627\u0644\u0635\u0641 \u0639\u0646\u062f \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631.")
